17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidFieldValueException;
37	import org.springframework.samples.petclinic.rest.advice.MissingRequiredFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
65	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
66	     */
67	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        List<String> missingFields = new ArrayList<>();
116	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
117	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
118	        requireNonBlank(missingFields, "address", ownerFieldsDto.getAddress());
119	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
120	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
121	        if (!missingFields.isEmpty()) {
122	            throw new MissingRequiredFieldsException(missingFields);
123	        }
124	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
125	        requireUniqueTelephone(normalizedTelephone);
126	        ownerFieldsDto.setTelephone(normalizedTelephone);
127	        if (ownerFieldsDto.getEmail() != null) {
128	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
129	        }
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        if (owner.getRegistrationDate() == null) {
133	            owner.setRegistrationDate(LocalDate.now());
134	        }
135	        this.clinicService.saveOwner(owner);
136	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
137	        headers.setLocation(UriComponentsBuilder.newInstance()
138	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
139	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
145	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
146	        if (currentOwner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        currentOwner.setAddress(ownerFieldsDto.getAddress());
150	        currentOwner.setCity(ownerFieldsDto.getCity());
151	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
152	        currentOwner.setLastName(ownerFieldsDto.getLastName());
153	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
154	        this.clinicService.saveOwner(currentOwner);
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Transactional
160	    @Override
161	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        this.clinicService.deleteOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Pet pet = petMapper.toPet(petFieldsDto);
179	        owner.setId(ownerId);
180	        pet.setOwner(owner);
181	        pet.getType().setName(null);
182	        this.clinicService.savePet(pet);
183	        PetDto petDto = petMapper.toPetDto(pet);
184	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
185	            .buildAndExpand(pet.getId()).toUri());
186	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner != null) {
194	            Pet currentPet = this.clinicService.findPetById(petId);
195	            if (currentPet != null) {
196	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
197	                currentPet.setName(petFieldsDto.getName());
198	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
199	                this.clinicService.savePet(currentPet);
200	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
209	        HttpHeaders headers = new HttpHeaders();
210	        Visit visit = visitMapper.toVisit(visitFieldsDto);
211	        Pet pet = new Pet();
212	        pet.setId(petId);
213	        visit.setPet(pet);
214	        this.clinicService.saveVisit(visit);
215	        VisitDto visitDto = visitMapper.toVisitDto(visit);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
217	            .buildAndExpand(visit.getId()).toUri());
218	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
219	    }
220	
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
237	     * whitespace-only), so the caller can reject the request listing every offending field.
238	     */
239	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
240	        if (value == null || value.isBlank()) {
241	            missingFields.add(fieldName);
242	        }
243	    }
244	
245	    /**
246	     * Normalizes a telephone number by removing every non-digit character and requires the result to
247	     * be exactly ten digits. Returns the 10-digit value to be stored and returned as {@code telephone}.
248	     *
249	     * @param telephone the raw telephone value from the request
250	     * @return the normalized 10-digit telephone number
251	     * @throws InvalidFieldValueException if the value is not exactly ten digits after stripping
252	     */
253	    private static String normalizeTelephone(String telephone) {
254	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
255	        if (digits.length() != 10) {
256	            throw new InvalidFieldValueException("telephone",
257	                "Telephone must contain exactly 10 digits after removing non-digit characters");
258	        }
259	        return digits;
260	    }
261	
262	    /**
263	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
264	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
265	     *
266	     * @param email the raw email value from the request (already known to be non-null)
267	     * @return the lower-cased email to be stored and returned
268	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
269	     */
270	    private static String normalizeEmail(String email) {
271	        String trimmed = email.trim();
272	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
273	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
274	        }
275	        return trimmed.toLowerCase(Locale.ROOT);
276	    }
277	
278	    /**
279	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
280	     * comparing on the digits-only form so differently-formatted stored numbers still collide.
281	     *
282	     * @param normalizedTelephone the incoming owner's normalized (10-digit) telephone
283	     * @throws DuplicateTelephoneException if another owner already uses this telephone
284	     */
285	    private void requireUniqueTelephone(String normalizedTelephone) {
286	        boolean taken = this.clinicService.findAllOwners().stream()
287	            .map(Owner::getTelephone)
288	            .filter(existing -> existing != null)
289	            .map(existing -> existing.replaceAll("\\D", ""))
290	            .anyMatch(normalizedTelephone::equals);
291	        if (taken) {
292	            throw new DuplicateTelephoneException(normalizedTelephone);
293	        }
294	    }
295	}
