/**
 * Normalizes a telephone number by removing every non-digit character and requires the result to
 * be exactly ten digits. Returns the 10-digit value to be stored and returned as {@code telephone}.
 *
 * @param telephone the raw telephone value from the request
 * @return the normalized 10-digit telephone number
 * @throws InvalidFieldValueException if the value is not exactly ten digits after stripping
 */
private static String normalizeTelephone(String telephone) {
    String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
    if (digits.length() != 10) {
        throw new InvalidFieldValueException("telephone",
            "Telephone must contain exactly 10 digits after removing non-digit characters");
    }
    return digits;
}

